require_once __DIR__.'/includes/auth.php';require_auth();$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='all')db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['id']]);else db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)($_POST['id']??0),$u['id']]);redirect('notifications.php');}$stmt=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$stmt->execute([$u['id']]);$items=$stmt->fetchAll();$pageTitle='Notifications';$pageSubtitle='Updates about your assets and shared work';$pageActions='<form method="post">'.csrf_field().'<input type="hidden" name="action" value="all"><button class="btn btn-light">Mark all read</button></form>';require __DIR__.'/includes/header.php';?>
<div class="card"><div class="list-group list-group-flush"><?php foreach($items as $n):?><div class="list-group-item p-3 <?=$n['is_read']?'':'bg-primary bg-opacity-10'?>"><div class="d-flex gap-3"><span class="stat-icon bg-primary bg-opacity-10 text-primary"><i class="bi bi-bell"></i></span><div class="flex-grow-1"><div class="d-flex justify-content-between"><strong><?=e($n['title'])?></strong><small class="text-muted"><?=e(date('M j, g:i A',strtotime($n['created_at'])))?></small></div><p class="mb-1 text-muted"><?=e($n['message'])?></p><?php if($n['link']):?><a class="small" href="<?=e(url($n['link']))?>">Open</a><?php endif;?></div><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-sm btn-light" title="Mark read"><i class="bi bi-check2"></i></button></form><?php endif;?></div></div><?php endforeach;?><?php if(!$items):?><div class="empty-state"><i class="bi bi-bell"></i><h2 class="h5 mt-3">You’re all caught up</h2></div><?php endif;?></div></div>
